#include <stdio.h>
#include <string.h>
int gcd(int a,int b){return b?gcd(b,a%b):a;}
int main(void){int a,b;scanf("%d%d",&a,&b);printf("%d",gcd(a,b));return 0;}

#include <stdio.h>
#include <string.h>
long fact(int n){return n<=1?1:n*fact(n-1);}
int main(void){int n;scanf("%d",&n);printf("%ld",fact(n));return 0;}

#include <stdio.h>
#include <string.h>
int sum(int a[],int n){int s=0,i;for(i=0;i<n;i++)s+=a[i];return s;}
int main(void){int n,a[100],i;scanf("%d",&n);for(i=0;i<n;i++)scanf("%d",&a[i]);printf("%d",sum(a,n));return 0;}

